    write_line(
        "1 - 2 = {int_calculator.calculate("-", 1, 2)}"
    );
    write_line(
        "1 * 2 = {int_calculator.calculate("*", 1, 2)}"
    );
    write_line(
        "1 / 2 = {int_calculator.calculate("/", 1, 2)}"
    );

    let from_memory =
        int_calculator.calculate_from_memory("-", 3);
    write_line("1 + 2 - 3 = {from_memory}");

